import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_op_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm>

__device__ __forceinline__ float clamp01(float v) {
    return fminf(fmaxf(v, 0.0f), 1.0f);
}

__global__ void fused_bias_clamp_scale_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    float scaling_factor,
    int N, int C, int H, int W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = N * C * H * W;
    if (idx < total_size) {
        int w = idx % W;
        int tmp = idx / W;
        int h = tmp % H;
        tmp /= H;
        int c = tmp % C;
        int n = tmp / C;

        float val = x[idx] + bias[c];
        val = clamp01(val);
        val *= scaling_factor;
        val = clamp01(val);
        val /= scaling_factor;
        out[idx] = val;
    }
}

torch::Tensor fused_bias_clamp_scale_cuda(torch::Tensor x, torch::Tensor bias, float scaling_factor) {
    auto sizes = x.sizes();
    const int N = sizes[0];
    const int C = sizes[1];
    const int H = sizes[2];
    const int W = sizes[3];

    auto out = torch::empty_like(x);

    int total_size = N * C * H * W;
    int block_size = 256;
    int grid_size = (total_size + block_size - 1) / block_size;

    fused_bias_clamp_scale_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        scaling_factor,
        N, C, H, W
    );

    return out;
}
"""

fused_op_cpp_source = r"""
torch::Tensor fused_bias_clamp_scale_cuda(torch::Tensor x, torch::Tensor bias, float scaling_factor);
"""

fused_op = load_inline(
    name="fused_op",
    cpp_sources=fused_op_cpp_source,
    cuda_sources=fused_op_source,
    functions=["fused_bias_clamp_scale_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model with fused custom CUDA kernel for bias addition, clamping, and scaling.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding
        )
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.scaling_factor = scaling_factor

    def forward(self, x):
        x = self.conv_transpose(x)
        x = fused_op.fused_bias_clamp_scale_cuda(x, self.bias, self.scaling_factor)
        return x

